package com.mahesh.empleave.leavebalance;import com.mahesh.empleave.leave.*;import jakarta.persistence.*;import lombok.*;import java.math.*;import java.time.*;@Entity @Getter @NoArgsConstructor(access=AccessLevel.PROTECTED) public class BalanceTransaction{@Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id;@ManyToOne(optional=false) private LeaveBalance balance;@ManyToOne private LeaveApplication application;@Column(nullable=false,precision=7,scale=2) private BigDecimal delta;@Column(nullable=false) private String reason;@Column(nullable=false) private LocalDateTime createdAt=LocalDateTime.now();public BalanceTransaction(LeaveBalance b,LeaveApplication a,BigDecimal d){this(b,a,d,a==null?"ENTITLEMENT_ADJUSTMENT":"LEAVE_ACCOUNTING");}public BalanceTransaction(LeaveBalance b,LeaveApplication a,BigDecimal d,String r){balance=b;application=a;delta=d;reason=r;}}
